select.example:
select {
case m1 := <-c1:
  fmt.Println(m1)
default:
  fmt.Println("nunggu...")
}

WaitGroup.example:
var wg sync.WaitGroup
for _, job := range jobs {
  wg.Go(func() {
    proses(job)
  })
}
wg.Wait()

Go.example:
var wg sync.WaitGroup
wg.Go(func() {
  fetch(url)
})
wg.Wait()

OnceValue.example:
config := sync.OnceValue(func() Config {
  return loadConfig()
})
fmt.Println(config())

OnceValues.example:
load := sync.OnceValues(func() (Config, error) {
  return readConfig()
})
cfg, err := load()

Pool.example:
pool := sync.Pool{New: func() any { return new(bytes.Buffer) }}
buf := pool.Get().(*bytes.Buffer)
defer pool.Put(buf)

Context.example:
ctx, cancel := context.WithTimeout(context.Background(), time.Second)
defer cancel()

select {
case <-ctx.Done():
  return ctx.Err()
case data := <-ch:
  return proses(data)
}

Ticker.example:
ticker := time.NewTicker(time.Second)
defer ticker.Stop()
for t := range ticker.C {
  fmt.Println(t)
}
